source('R/stile.R')
d<-leggi('campioni_modulo1.csv');u<-leggi('casuali_comuni_v3.csv')$u
out<-'risultati/M15';dir.create(out,recursive=TRUE,showWarnings=FALSE)
valida<-function(x){stopifnot(!anyDuplicated(x$id),all(is.finite(x$massa_g)),all(is.finite(x$volume_cm3)),all(x$massa_g>0),all(x$volume_cm3>0));invisible(TRUE)}
trasforma<-function(x){valida(x);q<-x;q$densita<-q$massa_g/q$volume_cm3;q}
pipeline<-function(x)aggregate(densita~stazione,trasforma(x),mean)
q<-trasforma(d);s<-pipeline(d)
verifica('input conservato e pipeline deterministica',!('densita'%in%names(d))&&identical(s,pipeline(d))&&nrow(s)==6)
verifica('densita manuale',abs(q$densita[1]-2.68)<1e-12)
errore<-tryCatch({trasforma(transform(d,volume_cm3=0));FALSE},error=function(e)TRUE)
verifica('volume nullo intercettato',errore)
salva('M15','F01',ggplot(q,aes(stazione,densita))+geom_point(colour=geo[1],size=2,position=position_jitter(width=.08,height=0,seed=17))+geom_point(data=s,shape=18,size=4,colour=geo[2])+scale_y_continuous(labels=fmt)+labs(x='Stazione',y='Densità (g/cm³)'))
ix<-matrix(floor(u[1:240]*24)+1,10,byrow=TRUE);b<-apply(ix,1,function(i)mean(q$densita[i]));boot<-data.frame(replica=1:10,media=b)
verifica('indici condivisi nel dominio',all(ix>=1&ix<=24))
write.csv(boot,file.path(out,'bootstrap_condiviso.csv'),row.names=FALSE)
salva('M15','F02',ggplot(boot,aes(replica,media))+geom_hline(yintercept=mean(q$densita),colour=geo[2],linetype=2)+geom_line(colour=geo[1],linewidth=.7)+geom_point(colour=geo[1],size=2)+scale_x_continuous(breaks=c(1,5,10))+scale_y_continuous(labels=fmt)+labs(x='Ricampionamento',y='Media (g/cm³)'))
set.seed(17);v1<-runif(8);set.seed(17);v2<-runif(8);verifica('seme nello stesso ambiente',identical(v1,v2))
delta<-sapply(0:5,function(k)max(abs(round(q$densita,k)-q$densita)))
rd<-data.frame(decimali=0:5,errore=pmax(delta,1e-16))
salva('M15','F03',ggplot(rd[1:3,],aes(decimali,errore))+geom_col(fill=geo[3],width=.55)+scale_x_continuous(breaks=0:2)+scale_y_continuous(labels=fmt)+labs(x='Cifre decimali conservate',y='Errore massimo (g/cm³)'))
write.csv(q,file.path(out,'dati_roundtrip.csv'),row.names=FALSE,na='NA');z<-read.csv(file.path(out,'dati_roundtrip.csv'))
verifica('roundtrip identificativi e valori',identical(q$id,z$id)&&max(abs(q$densita-z$densita))<1e-12)
verifica('tolleranza assoluta e relativa',all(abs(q$densita-z$densita)<=1e-12+1e-10*abs(q$densita)))
th<-data.frame(soglia=c(0,35,40,45,50,55));th$n<-sapply(th$soglia,function(t)sum(d$volume_cm3>=t));th$media<-sapply(th$soglia,function(t){v<-q$densita[d$volume_cm3>=t];if(length(v))mean(v) else NA_real_})
salva('M15','F04',ggplot(th,aes(soglia,n))+geom_step(colour=geo[1],linewidth=.8)+geom_point(colour=geo[1],size=2)+scale_x_continuous(breaks=c(0,20,40,55))+scale_y_continuous(breaks=c(0,8,16,24))+labs(x='Volume minimo (cm³)',y='Provini conservati'))
salva('M15','F05',ggplot(th[th$n>0,],aes(soglia,media))+geom_line(colour=geo[2],linewidth=.8)+geom_point(colour=geo[2],size=2)+scale_x_continuous(breaks=c(0,20,40,55))+scale_y_continuous(labels=fmt)+labs(x='Volume minimo (cm³)',y='Media selezionata (g/cm³)'))
verifica('annidamento dei filtri',all(diff(th$n)<=0)&&th$n[1]==24)
a<-data.frame(id=1:3,valore=c(0,NA,2));write.csv(a,file.path(out,'mancanti.csv'),row.names=FALSE,na='NA');aa<-read.csv(file.path(out,'mancanti.csv'),na.strings='NA')
verifica('zero e mancante conservati',aa$valore[1]==0&&is.na(aa$valore[2]))
f<-file.path(out,'originale_test.csv');g<-file.path(out,'copia_test.csv');writeLines('id,valore\nA,1',f);writeLines('id,valore\nA,1.0',g)
verifica('contenuto equivalente con byte diversi',unname(tools::md5sum(f))!=unname(tools::md5sum(g))&&isTRUE(all.equal(read.csv(f),read.csv(g))))
write.csv(s,file.path(out,'densita_stazioni.csv'),row.names=FALSE);write.csv(th,file.path(out,'sensibilita_soglia.csv'),row.names=FALSE)
jsonlite::write_json(list(media=mean(q$densita),stazioni=s,bootstrap=b,arrotondamento=delta,soglie=th),file.path(out,'valori.json'),pretty=TRUE,auto_unbox=TRUE,digits=12)
writeLines(capture.output(sessionInfo()),file.path(out,'ambiente.txt'))
